<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />

    <div class="option-box">
      <OptimizationReturn title="SEO Разделов">
        <template #option-slot="{ emitEvent }">
          <CustomInput
            v-model="comandName.value"
            :placeholder="comandName.name"
            @update:model-value="emitEvent"
          />
        </template>
      </OptimizationReturn>
      <div class="optimization-table__box">
        <CustomTable
          :ItemRows="itemRow"
          :headerRows="headerRows"
          :lineClamp="2"
          height="60px"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import CustomTable from '@/components/UI/CustomTable';
import OptimizationReturn from '@/components/SEO/OptimizationReturn';
import CustomInput from '@/components/UI/CustomInput';
import { getSeoSectionLog } from '@/services/apiTableAdmin.js';

const title = ref('SEO Разделов');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');

const comandName = ref({
  value: '',
  placeholder: 'поиск по номеру лога',
  name: 'поиск по номеру лога',
  ValidateType: 'empty',
  errorText: '',
});
const itemRow = ref([]);
const headerRows = [
  {
    name: '#',
    width: '68px',
    helper: false,
  },
  {
    name: 'Дата',
    helper: false,
    width: '74px',
  },
  {
    name: 'Сотрудники',
    helper: false,
    width: '148px',
  },
  {
    name: 'Событие',
    helper: false,
    width: '282px',
  },
  {
    name: 'Ссылка',
    helper: false,
    width: '343px',
  },
];
const getItemRow = async () => {
  const data = await getSeoSectionLog();

  itemRow.value = data?.data.map((item) => ({
    id: {
      value: item?.id,
      type: 'text',
      contenteditable: false,
    },
    date: {
      value: item?.updated_at,
      type: 'text',
      contenteditable: false,
    },
    user: {
      value: item?.user.username,
      type: 'link',
      contenteditable: false,
    },
    event: {
      value: item?.event,
      type: 'text',
      contenteditable: false,
    },
    link: {
      value: item?.link,
      type: 'text',
      contenteditable: false,
    },
  }));
};
// const handleButtonClick = (item) => {
//   console.log(item);
// };
onMounted(() => {
  getItemRow();
});
</script>

<style scoped lang="scss">
.option-box {
  margin-top: 20px;
  height: calc(100vh - 100px);
  box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
  border-radius: 4px;
  padding: 12px 24px;
}
.optimization {
  margin: 16px 24px 16px 16px;
  width: calc(100% - 50px);
  display: flex;
  flex-direction: column;
  @media (max-width: 1024px) {
    justify-content: space-between;
    height: calc(100vh - 60px);
  }
  &-table__box {
    height: calc(100% - 70px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  &-option {
    display: flex;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 24px 0;
    padding: 12px 24px;
    &__box {
      display: flex;
      flex-direction: column;
      width: 100%;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      &:first-child {
        justify-content: space-between;
      }
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
  }
}
</style>
